ORIGINAL_SOURCE_ITEM = shared.source_item


def scoped_source_item(source_id: str, verse: int, text: str) -> dict:
    result = ORIGINAL_SOURCE_ITEM(source_id, verse, text)
    if source_id == "en_tafheem_ul_quran":
        if verse <= 25:
            group_key, group_label = "23–25", "۴:۲۳–۲۵"
        elif verse <= 33:
            group_key, group_label = "26–33", "۴:۲۶–۳۳"
        else:
            group_key, group_label = "34–42", "۴:۳۴–۴۲"
        result["sourceUrl"] = TAFHEEM_GROUPS[group_key]
        result["cite"] = (
            f"مودودی، *تفہيم القرآن*، ذیلِ نساء ۴:{verse}؛ "
            f"شرحِ گروهیِ واقعیِ {group_label}."
        )
        result["evidence"] = (
            f"موضعِ بررسی: صفحهٔ گروهیِ واقعیِ {group_label}؛ "
            "شمارهٔ یادداشت و دامنهٔ آیه در خلاصه جدا شده است."
        )
    elif source_id == "ar_fayd_safi" and verse in FAYD_GROUPS:
        page_verse, group_label = FAYD_GROUPS[verse]
        result["sourceUrl"] = shared.SOURCE_META[source_id]["url"].format(verse=page_verse)
        result["cite"] = (
            f"فیض کاشانی، ۱۰۹۰ق، *الصافي في تفسير كلام الله الوافي*، "
            f"شرحِ گروهیِ نساء {group_label}؛ GreatTafsirs؛ چاپ/صفحهٔ کتاب احراز نشده."
        )
        result["evidence"] = (
            f"موضعِ بررسی: شرحِ گروهیِ واقعیِ {group_label} در GreatTafsirs؛ "
            "محدودهٔ متن با سرعنوان و آیاتِ همان صفحه مقابله شده است."
        )
    elif source_id in {"ar_tabari_qurancom", "ar_ibn_kathir_qurancom"}:
        result["evidence"] = (
            f"موضعِ بررسی: تفسیرِ عربیِ نساء ۴:{verse} در آرشیوِ ثابتِ Quran.com API؛ "
            "پیوندِ آیه‌محور جدا ثبت شده است."
        )
    elif source_id == "ar_jalalayn_qurancom":
        result["evidence"] = (
            f"موضعِ بررسی: صفحهٔ مستقیمِ جلالین برای نساء ۴:{verse}؛ "
            "خلاصه به همان آیه متصل است."
        )
    elif source_id == "ar_tusi_tibyan":
        result["evidence"] = (
            f"موضعِ بررسی: صفحهٔ مستقیمِ التبيان برای نساء ۴:{verse} در GreatTafsirs؛ "
            "چاپ و صفحهٔ کتاب احراز نشده است."
        )
    elif source_id == "ar_qe_arabic_moyassar":
        result["evidence"] = (
            f"موضعِ بررسی: متنِ محلیِ QuranEnc، التفسير الميسر، نساء ۴:{verse}؛ "
            "نسخهٔ ۱٫۰٫۰ در رجیستری ثبت شده است."
        )
    return result


# build_entry resolves source_item through this module global.
shared.source_item = scoped_source_item


def build_catalog(registry: dict) -> dict:
    collection = shared.build_catalog(registry)
    collection["id"] = COLLECTION_ID
    collection["title"] = "منابعِ تفسیریِ مورد استناد در بستهٔ نساء ۴:۲۵–۳۶"
    fayd_pages = sorted({
        shared.SOURCE_META["ar_fayd_safi"]["url"].format(verse=page_verse)
        for page_verse, _label in FAYD_GROUPS.values()
    })
    tusi_pages = [
        shared.SOURCE_META["ar_tusi_tibyan"]["url"].format(verse=verse)
        for verse in range(25, 37)
    ]
    jalalayn_pages = [
        shared.SOURCE_META["ar_jalalayn_qurancom"]["url"].format(verse=verse)
        for verse in range(25, 37)
    ]
    registry_by_id = {entry["id"]: entry for entry in registry["sources"]}
    for source in collection["items"]:
        source_id = source["id"]
        source["scope"] = "نساء ۴:۲۵–۳۶"
        if source_id in CLASSICAL_IDS:
            source["sourceUrl"] = shared.SOURCE_META[source_id]["url"].format(verse=25)
        if source_id == "ar_tusi_tibyan":
            source["sourceUrls"] = tusi_pages
        elif source_id == "ar_fayd_safi":
            source["sourceUrl"] = shared.SOURCE_META[source_id]["url"].format(verse=25)
            source["sourceUrls"] = [
                shared.SOURCE_META[source_id]["url"].format(verse=25), *fayd_pages,
            ]
        elif source_id == "ar_jalalayn_qurancom":
            source["sourceUrls"] = jalalayn_pages
        elif source_id == "ar_tabari_qurancom":
            source["sourceUrls"] = [
                "https://github.com/zeeyado/quran-ebook/blob/c9550fdd58b0feec36300dcc42cbb3d5a4ccafc5/release/quran_tafsir_tabari_v1.1.zip"
            ] + [
                shared.SOURCE_META[source_id]["url"].format(verse=verse)
                for verse in range(25, 37)
            ]
        elif source_id == "ar_ibn_kathir_qurancom":
            source["sourceUrls"] = [
                "https://github.com/zeeyado/quran-ebook/blob/c9550fdd58b0feec36300dcc42cbb3d5a4ccafc5/release/quran_tafsir_ibn_kathir_ar_v1.1.zip"
            ] + [
                shared.SOURCE_META[source_id]["url"].format(verse=verse)
                for verse in range(25, 37)
            ]
        elif source_id == "en_tafheem_ul_quran":
            source["sourceUrl"] = TAFHEEM_GROUPS["23–25"]
            source["sourceUrls"] = list(TAFHEEM_GROUPS.values())
        source["basis"] = {
            "ar_tabari_qurancom": (
                "مدخل‌های عربیِ آیاتِ ۴:۲۵–۳۶ در آرشیوِ نسخهٔ ۱٫۱ استخراج شدند و مواضعِ "
                "مرتبط با خلاصه‌ها، به‌ویژه گزارشِ اختلاف و ترجیحِ مؤلف، مقابله شدند؛ "
                f"SHA-256 آرشیو با رجیستری مقابله شد: {registry_by_id[source_id].get('upstreamZipSha256', '')}. "
                "این ثبت ادعای مقابلهٔ کاملِ همهٔ روایات و اسانید نیست؛ پیوندهای مستقیمِ آیه‌محور نیز آمده‌اند."
            ),
            "ar_ibn_kathir_qurancom": (
                "مدخل‌های عربیِ آیاتِ ۴:۲۵–۳۶ در آرشیوِ نسخهٔ ۱٫۱ استخراج شدند و مواضعِ "
                "مرتبط با خلاصه‌ها، به‌ویژه گزارشِ اختلاف و ترجیحِ مؤلف، مقابله شدند؛ "
                f"SHA-256 آرشیو با رجیستری مقابله شد: {registry_by_id[source_id].get('upstreamZipSha256', '')}. "
                "این ثبت ادعای مقابلهٔ کاملِ همهٔ روایات و اسانید نیست؛ پیوندهای مستقیمِ آیه‌محور نیز آمده‌اند."
            ),
            "ar_jalalayn_qurancom": "صفحه‌های مستقیمِ آیه‌محورِ جلالین برای نساء ۴:۲۵–۳۶ بررسی شدند؛ شرحِ هر آیه به همان آدرس پیوند خورده است.",
            "ar_tusi_tibyan": "صفحه‌های مستقیمِ GreatTafsirs برای ۴:۲۵–۳۶ بررسی شدند؛ چاپ یا شمارهٔ صفحهٔ کتاب حدس زده نشده است.",
            "ar_fayd_safi": "صفحهٔ ۴:۲۵ و شرح‌های گروهیِ واقعیِ ۴:۲۶–۲۹، ۴:۳۰–۳۱، ۴:۳۲–۳۳ و ۴:۳۴–۳۶ بررسی شدند؛ صفحه و دامنه در هر پرونده جدا ثبت است.",
            "ar_qe_arabic_moyassar": "متنِ محلیِ آیه‌به‌آیهٔ QuranEnc برای هر آیهٔ ۴:۲۵–۳۶ مقابله شد؛ شناسهٔ نسخهٔ ۱٫۰٫۰ در رجیستری موجود است.",
            "en_tafheem_ul_quran": "صفحه‌های گروهیِ واقعیِ ۴:۲۶–۳۳ و ۴:۳۴–۴۲ بررسی شدند؛ از صفحهٔ ۴:۲۳–۲۵ بخش‌هایِ دیده‌شدهٔ ۱–۳ از ۱۱ و یادداشت‌های ۴۴–۴۷ بازبینی شدند. یادداشتِ ۴۴ ذیلِ ۴:۲۴ و یادداشت‌های ۴۵–۴۷ ذیلِ ۴:۲۵ از هم جدا شده‌اند.",
        }[source_id]
    collection["comparativeCore"] = {
        "scope": "هر آیهٔ نساء ۴:۲۵–۳۶",
        "sunniSourceIds": sorted(SUNNI_IDS),
        "shiaSourceIds": sorted(SHIA_IDS),
        "note": "در هر یک از دوازده پرونده، سه تفسیرِ اهل‌سنت و دو تفسیرِ امامیه با خلاصهٔ منتسب و پیوندِ آیه‌محور یا دامنهٔ گروهیِ واقعی آمده‌اند؛ دو شرحِ معاصر و سه کاربستِ تحریریِ معناشناختی جدا ثبت شده‌اند.",
    }
    collection["notice"] = (
        "این مجموعه پیش‌نویسِ منبع‌محور است و نیازمندِ بازبینیِ تخصصی است؛ "
        "خلاصه‌ها نقلِ لفظی نیستند، صفحه‌های گروهی دامنهٔ محدود دارند، "
        "اطلاعاتِ چاپ و صفحهٔ کتاب حدس زده نشده و گزارشِ تاریخیِ برده‌داری "
        "تأییدِ اخلاقی یا راهنمایِ حقوقیِ امروز نیست."
    )
    return collection


def main() -> None:
    dossier = json.loads(DOSSIER_PATH.read_text(encoding="utf-8"))
    for verse, record in DATA.items():
        if not any("فولادوند/Tanzil" in note["cite"] for note in record["notes"]):
            record["notes"][0]["cite"] += (
                f"؛ متنِ قرآن و ترجمهٔ فولادوند/Tanzil، نساء ۴:{verse}."
            )
        dossier["verses"][f"4:{verse}"] = shared.build_entry(verse, record)

    dossier["batches"] = [batch for batch in dossier["batches"] if batch["id"] != BATCH_ID]
    nisa_end, nisa_gap = nisa_coverage(dossier["verses"])
    dossier["batches"].append({
        "id": BATCH_ID,
        "title": "بستهٔ سی‌وچهارم: نساء ۴:۲۵–۳۶؛ احکامِ نکاح، معاملات، خانواده و همسایگی",
        "range": "4:25–36",
        "count": 12,
        "status": f"۱۲ پروندهٔ آیه‌محور با دست‌کم پنج بندِ مستند در هر یک از شش فیلد؛ در هر آیه پنج تفسیرِ کهن (سه اهل‌سنت و دو امامیه)، دو شرحِ معاصر و سه کاربردِ معناشناختی آمده است؛ پیش‌نویسِ نیازمندِ بازبینیِ تخصصی؛ {nisa_gap}.",
    })
    dossier["batches"].sort(key=lambda batch: int(batch["id"].split("-")[1]))
    for batch in dossier["batches"]:
        if batch.get("range", "").startswith("4:") and "؛ نساء ۴:" in batch.get("status", ""):
            prefix = batch["status"].split("؛ نساء ۴:", 1)[0]
            batch["status"] = f"{prefix}؛ {nisa_gap}."

    end_fa = str(nisa_end).translate(str.maketrans("0123456789", "۰۱۲۳۴۵۶۷۸۹"))
    dossier["notice"] = (
        "این پرونده‌ها پیش‌نویس‌های تحریریِ منبع‌محورند و بازبینیِ تخصصی را پشت سر نگذاشته‌اند. "
        f"نساء در این checkout بازهٔ ۴:۱–{end_fa} را پوشش می‌دهد؛ {nisa_gap}. "
        "بسته‌های یونس بازه‌های ۱۰:۴۹–۶۰، ۱۰:۶۱–۷۲ و ۱۰:۷۳–۸۴ را پوشش می‌دهند؛ برای ۱۰:۱–۴۸ پرونده‌ای ساخته نشده است. "
        "این داده‌ها ادعای تکمیلِ هیچ‌یک از دو سوره یا کل قرآن را نمی‌کنند. خلاصه‌ها نقلِ لفظی نیستند؛ اختلافِ اقوال و دامنهٔ واقعیِ صفحاتِ گروهی جدا ثبت شده است."
    )
    method = dossier["editorialMethod"]
    for stale in (
        "نساء ۴:۱۳–۱۷۶ هنوز در این checkout پوشش ندارد",
        "نساء ۴:۱۳–۱۷۶ هنوز پوشش ندارد",
        "نساء ۴:۲۵–۱۷۶ هنوز پوشش ندارد",
        "نساء ۴:۳۷–۱۷۶ هنوز پوشش ندارد",
    ):
        method = method.replace(stale, nisa_gap)
    method = method.replace(f"{nisa_gap} در این checkout", nisa_gap)
    addition = (
        " در بستهٔ نساء ۴:۲۵–۳۶، برای هر آیه سه تفسیرِ اهل‌سنت و دو تفسیرِ امامیه، دو شرحِ معاصر و سه کاربستِ جداگانهٔ ایزوتسو، فیلمور و معناشناسیِ شناختی آمده است. "
        "اختلافِ قرائتِ «أُحصِنَّ» در ۴:۲۵، چند معنای «أنفسكم» در ۴:۲۹، اختلافِ تعریفِ کبائر در ۴:۳۱، برداشت‌های جنسیتیِ ۴:۳۲، نسخ یا بقایِ پیمانِ ارث در ۴:۳۳، و اختلافِ معنای قوامه و اختیارِ حکمین در ۴:۳۴–۳۵ یکسان‌سازی نشده‌اند. "
        "تفهيم القرآن به دامنه‌های واقعیِ ۴:۲۳–۲۵، ۴:۲۶–۳۳ و ۴:۳۴–۴۲ ارجاع می‌دهد؛ یادداشتِ ۴۴ ذیلِ ۴:۲۴ از یادداشت‌های ۴۵–۴۷ ذیلِ ۴:۲۵ جداست. "
        "گزارشِ برده‌داری و خشونتِ زناشویی در منابع، تأیید یا راهنمایِ حقوقیِ معاصر نیست. "
        f"این دوازده پرونده پیش‌نویس‌اند و نیازمندِ بازبینیِ تخصصی هستند؛ {nisa_gap}."
    )
    if "در بستهٔ نساء ۴:۲۵–۳۶" not in method:
        method += addition
    dossier["editorialMethod"] = method
    DOSSIER_PATH.write_text(json.dumps(dossier, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    registry = json.loads((STATIC / "tafsir-sources.json").read_text(encoding="utf-8"))
    catalog = json.loads(CATALOG_PATH.read_text(encoding="utf-8"))
    catalog["collections"] = [
        collection for collection in catalog["collections"] if collection["id"] != COLLECTION_ID
    ]
    catalog["collections"].append(build_catalog(registry))
    catalog["version"] = max(int(catalog.get("version", 0)), 10)
    CATALOG_PATH.write_text(json.dumps(catalog, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"Added {len(DATA)} dossiers; total={len(dossier['verses'])}; batch=4:25–36")


if __name__ == "__main__":
    main()
